def Hamming_Distance(x, y):
    # Initialize the distance to 0
    dist = 0
    # Loop over the bits of both numbers
    for i in range(64):
        # If the i-th bit of x and y differ, increment the distance
        if (x >> i) & 1 != (y >> i) & 1:
            dist += 1
    return dist
