def find_kth(nums1, nums2, target1, target2, k):
    if not nums1:
        return nums2[k - 1]
    if not nums2:
        return nums1[k - 1]

    n, m = len(nums1), len(nums2)
    if n < m:
        return find_kth(nums2, nums1, target2, target1, k)

    i, j = min(target1 - 1, n), min(target2 - 1, m)
    x, y = nums1[i], nums2[j]

    # If x is the rightmost in nums1, the k-th element is y
    if i == n - 1:
        return y

    # If x is the rightmost in nums2 and y is the rightmost in nums2, the k-th element is x
    if j == m - 1:
        return x

    if x <= y:
        return find_kth(nums1[i + 1:], nums2, target1 - i - 1, target2, k)
    else:
        return find_kth(nums1, nums2[j + 1:], target1, target2 - j - 1, k - 1)
