def find_kth(arr1, arr2, k, N, M):  
    ptr1, ptr2 = 0, 0  

    # Traverse both arrays until k is reduced to 0
    while k > 0 and ptr1 < N and ptr2 < M:  
        if arr1[ptr1] < arr2[ptr2]:  
            k -= 1
            ptr1 += 1
        else:  
            k -= 1
            ptr2 += 1  

    # If k is still positive, move pointer of the bigger array
    if k > 0:  
        if ptr1 == N:  
            return arr2[ptr2 + k - 1]  
        else:  
            return arr1[ptr1 + k - 1]  
    else:  
        return arr2[ptr2]  
