def min_coins(coins, amount, total_amount):
    # This problem can be solved using dynamic programming.
    # Create a DP table. Then update the DP table using the first
    # row and last column of a 2D grid.
    # Time complexity : O(coins size*amount size), Space complexity : O(amount size)
    dp = [[total_amount+1]*total_amount for _ in range(len(coins)+1)]
    dp[0] = [0 for _ in range(total_amount+1)]

    for i in range(1,len(coins)+1):
        for j in range(1,total_amount+1):
            if j < coins[i-1]:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = min(dp[i][j-coins[i-1]]+1, dp[i-1][j])

    return dp[-1][-1]
