def super_seq(str1, str2, p1, p2):
    # Initialize the dp table with the length of str1 columns by str2 rows
    dp = [[0] * p2 for _ in range(p1 + 1)]
    # Fill the dp table
    for i in range(1, p1 + 1):
        for j in range(1, p2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    # The length of the super sequence is the sum of the lengths of the subsequences minus the length of their intersection
    return p1 + p2 - dp[p1][p2]
