def rencontres_number(n_depth, k_particle):
    matrix_size = 2 * n_depth + 1
    matrix = [[0 for _ in range(matrix_size)] for _ in range(matrix_size)]
    matrix[n_depth][n_depth] = 1
    for i in range(n_depth):
        matrix[n_depth + k_particle - i - 1][n_depth + k_particle + i - 1] = 1

    for i in range(1, n_depth):
        for j in range(1, matrix_size - 1):
            if i == j:
                matrix[i][j] += 3 * matrix[i + 1][j]
            else:
                matrix[i][j] += matrix[i + 1][j] + matrix[i][j - 1] + matrix[i + 1][j - 1]

    return matrix[n_depth][n_depth]
```

