def join_tuples(tuples):
    # Create an empty dictionary to group tuples by their initial elements
    grouped_tuples = {}
    # Iterate through each tuple in the input list
    for t in tuples:
        # Extract the initial element from the tuple
        initial_element = t[0]
        # If the initial element is not already a key in the dictionary, add it
        if initial_element not in grouped_tuples:
            grouped_tuples[initial_element] = [t]
        else:
            # If the initial element is already a key, append the current tuple to the list
            grouped_tuples[initial_element].append(t)
    # Extract the grouped tuples as list of tuples
    return list(grouped_tuples.values())
