def coin_change(coins, N, A):
    # Initialize the dp table with A+1 columns (A+1 represents the largest parameter set - A)
    dp = [[0 for _ in range(A+1)] for _ in range(len(coins)+1)]

    # Base cases
    for i in range(len(coins)+1):
        for j in range(A+1):
            if j == 0:
                dp[i][j] = 1
            elif i == 0 and j != 0:
                dp[i][j] = 0

    # Fill the dp table
    for i in range(1, len(coins)+1):
        for j in range(1, A+1):
            if coins[i-1] <= j:
                dp[i][j] = dp[i-1][j] + dp[i][j-coins[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Return the result
    return dp[len(coins)][A]
