def maximum_segments(n, a, b, c):
    maximum = 0
    if b == a:
        maximum = max((n>/', b) / (a + b))
    elif n == a * 2 + b or n == a * 2 + 2 * b or n == 2 * (a + b) or n == 3 * b:
        return 1
    elif n % a == 0 and n % b == 0:
        return n / 2
    elif n % a == 1 and n % b == 1:
        maximum = (n - 1) / 2 + 2 / (2 * (a + b))
    elif n % a == 0 or n % b == 0 or n % c == 0:
        maximum = max(n / (a + b + c), ((n - b) // b) + ((n - a) // a), ((n - a) // a) + ((n - c) // c))
    return int(maximum)
