def min_cost(cost, m, n):
    #Create a list for the minimum cost to reach each cell
    min_cost_matrix = [cost[0][0]]
    for i in range(1, n+1):
        for j in range(i+1, m+1):
            #Calculate the minimum cost to reach the current cell
            if i == 0 and j == 0:
                min_cost_matrix.append(cost[0][0])
            elif i == 0:
                min_cost_matrix.append(cost[i][j] + min_cost_matrix[j-1])
            elif j == 0:
                min_cost_matrix.append(cost[i][j] + min_cost_matrix[i-1])
            else:
                min_cost_matrix.append(cost[i][j] + min(min_cost_matrix[i-1], min_cost_matrix[j-1]))
    return min_cost_matrix[m][n]
