def min_cost(cost, m, n):
    # Create an array to store minimum step to reach each cell
    movements = [[float('inf')] * (n+1) for _ in range(m+1)]
    movements[0][0] = 0  # Starting point has cost 0

    # Path from (0,0) to each cell
    paths = [[(0,0)] for _ in range(m+1)] 

    # Loop from (1,1) to (m,n)
    for i in range(1, m+1):
        for j in range(1, n+1):
            # Update movements[i][j] to check if it is minimum cost path in that cell
            movements[i][j] = min(cost[i][j] + movements[i-1][j], cost[i][j] + movements[i][j-1])
            # Update shortest path in that cell
            if movements[i][j] == movements[i-1][j]:
                paths[i][j] = paths[i-1][j]
            if movements[i][j] == movements[i][j-1]:
                paths[i][j] = paths[i][j-1] + [(i,j)]

    # Function to trace back the path
    def trace_path(x, y):
        if x == 0 or y == 0:
            return paths[x][y]
        if movements[x][y] == movements[x-1][y]:
            return trace_path(x-1, y) + [(x,y)]
        else:
            return trace_path(x, y-1) + [(x,y)]

    # Return the minimum cost path to (m,n) and the path itself
    return movements[m][n], trace_path(m,n)
```

