def find_dissimilar(tuple1, tuple2):
    # Create two sets from the tuples, removing duplicates
    if type(tuple1) is tuple or type(tuple2) is tuple:
        # Convert the tuples to sets
        set1, set2 = set(tuple1), set(tuple2)
