def find_Min_Swaps(binary, n):
    total_swaps = 0
    swaps_needed = n - sum(binary)  # Maximum number of swaps possible
    current_swaps = 0
    greater_space_index = -1

    for i in range(n):
        if binary[i] > 0:  # Left part of increasing subarray (bubble sort principle)
            if greater_space_index != -1 and binary[greater_space_index] <= binary[i]:
                current_swaps += i - greater_space_index - 1
                greater_space_index = -1
            else:
                greater_space_index = i

    total_swaps += swaps_needed - current_swaps  # Add the remaining swaps needed to sort the right part
    return swaps_needed
```

