def find_Min_Swaps(arr,maxSize):
    #Count number of zeros and ones in the array
    oneCount=0
    zeroCount=0
    for i in arr:
        if i == 0:
            zeroCount+=1
        else:
            oneCount+=1

    #The process of the question is same as finding the number of inversions
    invCount = 0    
    for i in range(maxSize):
        for j in range(i+1,maxSize):
            if arr[i] == 0 and arr[j] == 1: 
                invCount += 1

    #If there are two consecutive zeros then swap them 
    #This is because we can only swap two adjecent elements
    while zeroCount <= oneCount:
        if arr[i] == 0 and arr[i+1] == 0: 
            arr[i],arr[i+1] = arr[i+1],arr[i] 
            invCount+=1
            zeroCount+=1
            oneCount-=1
        i+=1
    return invCount
