        if m > 0 and arr[m] < arr[m-1]:
            return arr[m-1]
        if m + 1 < h and arr[m] > arr[m+1]:
            return arr[m]

        if arr[m] > arr[l]:
            return find_Max(arr, m+1, h)
        return find_Max(arr, l, m-1)
    return -1
