def get_median(nums1, nums2, n):
    if n == 1:
        return nums1[0]
    mid = n // 2

    if nums1[mid] == nums2[mid]:
        return nums1[mid]

    if nums1[mid] < nums2[mid]:
        left = max(nums1[:mid], nums1[mid+1:mid+n//2+1])
        right = min(nums2[:mid], nums2[mid+1:mid+n//2+1])
    else:
        left = max(nums2[:mid], nums2[mid+1:mid+n//2+1])
        right = min(nums1[:mid], nums1[mid+1:mid+n//2+1])

    return (left + right)/2.0
```

