from typing import List

def get_median(sorted_array1: List[int], sorted_array2: List[int], n: int) -> float:
    i, j, mid = 0, 0, 0

    # If odd number of elements, middle element is the median
    if n % 2 == 1:
        while j < n:
            if sorted_array1[i] <= sorted_array2[j]:
                mid = sorted_array1[i]
                i += 1
            else:
                mid = sorted_array2[j]
                j += 1

        return mid

    # If even number of elements, average of two middle elements is the median
    else:
        # Find the first middle element
        while j < n:
            if sorted_array1[i] <= sorted_array2[j]:
                mid += sorted_array1[i]
                i += 1
            else:
                mid += sorted_array2[j]
                j += 1

        # Calculate the median by averaging two middle elements
        if mid == 0:
            return 0
        else:
            return mid / 2
