def maxAverageOfPath(matrix, n):
    max_avg_n = 0
    for i in range(n):
        for j in range(n):
            mn = matrix[i][j]
            for k in range(n ** 2):
                x = i + (k // n) - (k % n)
                y = j + (k // n)
                if x >= 0 and x < n and y >= 0 and y < n:
                    mn = max(mn, matrix[x][y])
            max_avg_n = max(max_avg_n, mn / (k + 1))
    return max_avg_n
