def maxAverageOfPath(matrix, n):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def dfs(x, y, sum_so_far, path_count):
        if not is_valid(x, y): return
        sum_so_far += matrix[x][y]
        path_count += 1
        global max_avg
        if max_avg < sum_so_far / path_count:
            max_avg = sum_so_far / path_count
        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            dfs(x + dx, y + dy, sum_so_far, path_count)

    max_avg = 0
    for i in range(n):
        for j in range(n):
            dfs(i, j, matrix[i][j], 1)
    return max_avg
