def maxAverageOfPath(values, n):
    maxAvg = float('-inf')  # Initialize max average as negative infinity
    paths = []
    # Generate all permutations of input values
    for perm in permutations(values):
        avg = 0
        for i in range(n):
            for j in range(n):
                # Track the subarray while traversing the matrix
                for k in range(j, n):
                    avg += perm[i*n + k]
                if avg / n > maxAvg:
                    # Update max average if found a path with higher average
                    maxAvg = avg / n
        paths.append(perm)  # Track all possible paths
    return maxAvg, paths  # Return the maximum average and all paths
