        if path_len == n:
            return sum  
        max_val = 0
        if start_row > 0:
            max_val = max(max_val, max_value_sum(start_row - 1, start_col, sum + matrix[start_row - 1][start_col], path_len + 1, total_rows, total_cols))
        if start_col < total_cols - 1:
            max_val = max(max_val, max_value_sum(start_row, start_col + 1, sum + matrix[start_row][start_col + 1], path_len + 1, total_rows, total_cols))
        if start_row < total_rows - 1:
            max_val = max(max_val, max_value_sum(start_row + 1, start_col, sum + matrix[start_row + 1][start_col], path_len + 1, total_rows, total_cols))
        if start_col > 0:
            max_val = max(max_val, max_value_sum(start_row, start_col - 1, sum + matrix[start_row][start_col - 1], path_len + 1, total_rows, total_cols))
        return max_val

    max_sum = 0
    for i in range(n):
        for j in range(n):
            max_sum = max(max_sum, max_value_sum(i, j, matrix[i][j], 1, n, n))
    return max_sum / (n * n)
