def lbs(arr):
    # Find longest increasing subsequence
    def LMS(arr):
        L = [1] * len(arr)
        for i in range(1, len(arr)):
            for j in range(i):
                if arr[j] < arr[i]:
                    L[i] = max(L[i], L[j] + 1)
        return max(L)

    # Find longest decreasing subsequence
    def LDS(arr):
        RevArr = arr[::-1]
        L = [1] * len(RevArr)
        for i in range(1, len(RevArr)):
            for j in range(i):
                if RevArr[j] < RevArr[i]:
                    L[i] = max(L[i], L[j] + 1)
        return max(L)

    # Find the longest bitonic subsequence by combining LMS and LDS
    return LMS(arr) + LDS(arr) - 1
