def lbs(arr):
    # Find longest increasing subsequence
    lis = [1]*len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j]+1:
                lis[i] = lis[j]+1
    # Find longest decreasing subsequence
    dls = [1]*len(arr)
    for j in range(1, len(arr)):
        for i in range(j):
            if arr[j] < arr[i] and dls[j] < dls[i]+1:
                dls[j] = dls[i]+1
    # Find longest bitonic subsequence
    lbs = [0]*len(arr)
    for i in range(len(arr)):
        lbs[i] = lis[i] + dls[i] - 1
    return max(lbs)
