def dealnnoy_num(n, k):
    def binomial_coefficient(n, k):
        if k > n - k:
            k = n - k
        result = 1
        for i in range(k):
            result *= (n - i)
            result //= (i + 1)
        return result
    return binomial_coefficient(n + k, k) - binomial_coefficient(k + 1, k)
