def dealnnoy_num(n, k):
    """Find the nth Delannoy number"""
    # Base cases for Delannoy numbers
    if n == 0 and k == 0:
        return 1
    elif n == k:
        return 1
    elif k == 0:
        return 0
    # Recursive calculation of Delannoy numbers
    return dealnnoy_num(n - 1, k - 1) + dealnnoy_num(n, k - 1)
