def rencontres_number(n, m):
  # Ensure we're dealing with natural numbers
  if n <= 0 or not (1 <= m <= n):
    raise ValueError("n and m must be positive integers satisfying 1 <= m <= n")

  # Calculate the ways to pair m distinct men and n distinct women
  prod = n
  for i in range(1, m):
    prod *= (n - i + 1)

  # Calculate the number of rencontres given k pairs
  def cnt_rec(n, k):
    if k == 0 or k == n:
      return 1
    if n == 0:
      return 0
    return cnt_rec(n-1, k-1) + cnt_rec(n-1, k)

  # Calculate total rencontres
  return prod * cnt_rec(m, m+1)
```

