def max_sum_pair_diff_lessthan_K(arr, n, k):
    def partition(arr, low, high):
        i = (low - 1)
        pivot = arr[high]
        for j in range(low, high):
            if arr[j] <= pivot:
                i = i + 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return (i + 1)

    def quick_select(arr, low, high, k):
        if low == high:
            return arr[low]
        pi = partition(arr, low, high)
        if pi == k:
            return arr[pi]
        elif k < pi:
            return quick_select(arr, low, pi - 1, k)
        else:
            return quick_select(arr, pi + 1, high, k)

    def max_pair_diff(arr, n, k):
        arr.sort()
        return quick_select(arr, 0, n - 1, n // 2)

    max_diff = 0
    for i in range(0, n - 1):
        if max_pair_diff(arr, i, k) >= k:
            max_diff = max(max_diff, (arr[n - 1] - arr[i]))
    return max_diff
```

