def maxAverageOfPath(matrix, n):
    if n == 1:
        return matrix[0][0] 
    cache = {}  # To memoize already computed averages

    def avgPath(start, end):
        if (start, end) in cache:
            return cache[(start, end)]  # If already computed, return the cached value
        if start > end:
            return float('-inf')  # Invalid path, return negative infinity
        if start == end:
            return matrix[start][end]  # Single cell, return its value

        # Explore all possible paths from start to end
        curr_max = 0
        for i in range(start, end+1):
            path_max = max(avgPath(start, i) + avgPath(i+1, end), matrix[start][end])
            curr_max = max(curr_max, path_max)

        cache[(start, end)] = curr_max  # Cache the current maximum to avoid repeated calculations
        return curr_max

    return avgPath(0, n-1)  # Call the recursive function with the entire matrix
```

