def maxAverageOfPath(m, n):
    if not m or not m[0]:
        return 0
    dist = [[0 for _ in range(n)] for _ in range(n)]
    path = [[float(\'INF\') for _ in range(n)] for _ in range(n)]
    for k in range(n):
        dist[k][k] = 0
        path[k][k] = 1
    for stop in range(1, n):
        for i in range(n - stop):
            j = i + stop
            for limit in range(i, j):
                l1 = dist[i][limit]
                l2 = dist[limit + 1][j]
                dist[i][j] = min(l1, l2) + m[i][j]
                if dist[i][j] > path[i][j - 1]:
                    path[i][j] = path[i][j - 1] + m[i][j]
    return path[0][-1] / n
