    for row in matrix:
        # Convert the row into a tuple to ensure immutability and easy comparison
        row_tuple = tuple(row)
        # Check if the row has already been seen
        if row_tuple in seen:
            matrix.remove(row)  # Remove the duplicate row
        else:
            seen.add(row_tuple)  # Add the row to the seen set
    return matrix
