def lobb_num(a, b):
    if b > a: # Swap a and b if b is greater than a
        a, b = b, a

    lobb = 0
    current = 1
    for _ in range(a):
        lobb += Republican_move(a, b, current)
        current = next_move(current, a, b)
    return lobb

def Republican_move(a, b, current):
    current += a
    while (current - b) % a != 0:
        current += 1
    return current

def next_move(current, a, b):
    while (current - a) % b != 0:
        current += 1
    return current
```

