def min_Swaps(binary1, binary2):
    length = len(binary1)
    left_count = 0
    for i in range(length):
        if binary1[i] != binary2[i]:
            if binary1[i] == "0":  # For a 1 in binary1, we need to swap
                while binary1[i] != binary2[i]:
                    i += 1
            else:  # For a 0 in binary1, we need to replace it with a 1
                while binary1[i] != binary2[i]:
                    binary1[i] = "1"  # Replace non-zero with zero to make them the same
                    left_count += 1
    return left_count
