def find_kth(A, B, len_A, len_B, K):
    if len_A == 0:
        return B[K - 1]
    if len_B == 0:
        return A[K - 1]
    if K == 1:
        return min(A[0], B[0])
    mid_A = len_A // 2
    mid_B = len_B // 2
    if mid_A + mid_B < K:
        if A[mid_A] < B[mid_B]:
            return find_kth(A[mid_A + 1:], B, len_A - mid_A - 1, len_B, K - mid_A - 1)
        else:
            return find_kth(A, B[mid_B + 1:], len_A, len_B - mid_B - 1, K - mid_B - 1)
    else:
        if A[mid_A] < B[mid_B]:
            return find_kth(A, B[:mid_B], len_A, mid_B, K)
        else:
            return find_kth(A[:mid_A], B, mid_A, len_B, K)
