def Seq_Linear(seq):
    # Begin by checking if the sequence is empty or just a single element
    if len(seq) <= 1:
        return "Linear Sequence"

    # Loop through each pair of consecutive elements in the sequence
    for i in range(1, len(seq)):
        # If any two consecutive elements differ by more than 2, return "Not Linear Sequence"
        if seq[i] - seq[i-1] > 2 or seq[i] - seq[i-1] < -2:
            return "Not Linear Sequence"

    # If no two consecutive elements differ by more than 2, return "Linear Sequence"
    return "Linear Sequence"
```

