def second_frequent(llist):
    # Create a frequency dictionary
    freq_dict = {}
    for item in llist:
        if item in freq_dict:
            freq_dict[item] += 1
        else:
            freq_dict[item] = 1

    # Find the maximum frequency
    max_freq = max(freq_dict.values())

    # Find the second highest frequency
    second_max_freq = None
    for value in freq_dict.values():
        if value > 1 and (second_max_freq is None or value > second_max_freq):
            second_max_freq = value

    # Find the second most frequent string
    second_most_freq = [item for item, freq in freq_dict.items() if freq == second_max_freq]

    # Return the first item in the list, as the order of appearance is not guaranteed in Python dicts
    return second_most_freq[0]
