    freq_map = {}
    # Count frequency of each item
    for item in items:
        if item in freq_map:
            freq_map[item] += 1
        else:
            freq_map[item] = 1
    # Filter items with frequency greater than 1 to get repeated ones
    repeated_items = [item for item in freq_map if freq_map[item] > 1]
    # Sort the repeated items by frequency in descending order
    repeated_items.sort(key=lambda x: freq_map[x], reverse=True)
    # Return the second most frequent item, or None if there's no second most frequent
    if len(repeated_items) >= 2:
        return repeated_items[1]
    else:
        return None
```

