    arr.sort()  # Sort the array to make it easier to find the triplet
    n = len(arr)

    for i in range(n):
        left, right = i + 1, n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == sum_to_find:
                return (arr[i], arr[left], arr[right])
            elif current_sum < sum_to_find:
                left += 1
            else:
                right -= 1

