def occurance_substring(s, substr):
    occurrances = []
    indexes = []
    while substr in s:
        pos = s.find(substr, index)
        occurrances.append(pos)
        if pos == index:       # If the matched substr is at the beginning of the string
            occurrances.append(index)
        indexes.append(pos)
        s = s[pos + 1:]      # The substring is matched, move to the next position
    if occurrances == []:
        return ('', -1, -1), ('', -1, -1)
    return (''.join([str(_)+',' for _ in occurrances]), min(indexes), max(indexes))
```

