def count_Fac(z):
    # A list to store all distinct prime factors of z
    res = []
    
    # Divide z by all prime numbers and add them to the list
    for i in range(2, int(z ** 0.5) + 1):
        while z % i == 0:
            if i not in res:
                res.append(i)
            z //= i
    
    # For the prime number z itself, if it's greater than 1
    if z > 1:
        res.append(z)
    
    # Return the number of distinct prime factors
    return len(res)

