def lbs(arr) -> int:
    n, dp, stack = len(arr), [1]*n, []

    for i in range(n):     
        while stack and arr[i] > arr[stack[-1]]:
            dp[stack.pop()] = dp[i] + 1

        stack.append(i)

    dp_2 = [1]*n
    stack.clear()

    for i in range(n-1, -1, -1):     
        while stack and arr[i] > arr[stack[-1]]:
            dp_2[stack.pop()] = dp_2[i] + 1

        stack.append(i)

    dp = max([min(dp[i], dp_2[i]) for i in range(n)])
    return dp
