    asc = [None] * N
    dec = [None] * N

    # Find the longest increasing subsequence ending at each position
    for i in range(N):
        for j in range(i):
            if arr[i] > arr[j] and asc[i] == None or asc[i] < asc[j] + 1:
                asc[i] = asc[j] + 1

    # Find the longest decreasing subsequence starting at each position
    for i in range(N-1, -1, -1):
        for j in range(i+1, N):
            if arr[i] > arr[j] and dec[i] == None or dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # Calculate the length of the longest bitonic subsequence
    lbs_length = 0
    for i in range(N):
        lbs_length = max(lbs_length, asc[i] + dec[i] - 1)

