def find_First_Missing(arr, start, end):
    low = start
    high = end
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] != mid:
            if mid == 0 or arr[mid-1] == mid-1:
                return mid
            high = mid - 1
        else:
            low = mid + 1
    return end + 1
