def min_Swaps(s1, s2):
    total_swaps, swapscount = 0, 0
    N = len(s1)
    for i in range(N):
        # If different pairs are found, perform the swap
        if s1[i] != s2[i]:
            total_swaps += 1
            # Count swaps required for the pair to match
            for j in range(i + 1, N):
                if s1[j] == s2[i]:
                    s1[i], s1[j] = s1[j], s1[i]
                    swapscount += 1   

    # Each swap affects 2 pairs, hence we need to divide by 2
    return Swapscount // 2
```

