                max_index1 = i
            elif arr[i] > arr[min_index]:
                min_index = i
        else:
            if i < min_index1Index:
                min_index1Index = i
    return max(arr[min_index], arr[min_index1Index]) * max(arr[max_index], arr[max_index1])
