def lbs(arr):
    """
    Find the longest bitonic subsequence for the given array.

    Parameters:
    arr (list): The input array.

    Returns:
    int: The length of the longest bitonic subsequence.
    """
    cresc, decr = [1]*len(arr), [1]*len(arr)

    # Find the increasing subsequence lengths
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j] and cresc[i] < cresc[j] + 1:
                cresc[i] = cresc[j] + 1

    # Find the decreasing subsequence lengths
    for i in range(len(arr)-2, -1, -1):
        for j in range(i+1, len(arr)):
            if arr[i] > arr[j] and decr[i] < decr[j] + 1:
                decr[i] = decr[j] + 1

    # The length of the longest bitonic subsequence is the maximum sum of increasing and decreasing subsequences minus 1
    return max(map(lambda x, y: x+y-1, cresc, decr))
