def dealnnoy_num(n, k):
    # initialize a matrix
    matrix = [[0]*(k+1) for _ in range(n+1)]

    # initialize base case
    matrix[0][0] = 1
    for i in range(n+1):
        matrix[i][0] = 1

    # fill the matrix using binomial coefficient formulas
    for i in range(1, n+1):
        for j in range(1, k+1):
            matrix[i][j] = matrix[i-1][j-1] + matrix[i-1][j]

    return matrix[n][k]  # return the nth delannoy number
