    # d(n, k) = d(n-1, k) + d(n-1, k-1)
    if n == 0 or k <= 0 or n < k:
        return 0
    if n == k or k == 1:
        return 1
    return dealnnoy_num(n-1, k) + dealnnoy_num(n-1, k-1)
