def find_First_Missing(arr,low,high):
    if(high >= low and low <= len(arr)):
        mid = (low+high)//2
        # If the element at mid equals mid, then the first missing
        # number is in the right half.
        if(arr[mid] == mid):
            return  find_First_Missing(arr,mid+1,high)
        # If the element at mid is less than mid, then there must be
        # a number missing in the left half.
        elif(arr[mid] < mid):
            return find_First_Missing(arr,low,mid-1)
        # If the element at mid is greater than mid, then the first
        # missing number is in the right half.
        else:
            return find_First_Missing(arr,mid+1,high)
    # If the array is empty or the wrong indices are provided
    return 1 if len(arr) == 0 else -1
