def super_seq(str1, str2, m, n):
    # Create a DP table to store lengths of longest common subsequences
    dp = [[0 for i in range(n+1)] for j in range(m+1)]

    # Build the DP table
    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # The length of the longest common subsequence is dp[m][n]
    # The length of the shortest supersequence is (m + n - dp[m][n])
    return m + n - dp[m][n]
```

