def super_seq(a, b, la, lb):
    dp = [[0] * (lb + 1) for _ in range(la + 1)]

    for i in range(la + 1):
        for j in range(lb + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1)

    return dp[la][lb]
