    # If there is only one element, return it
    if l == r:
        return arr[l]

    # Find the mid point
    mid = (l + r) // 2

    # Check if the right half is sorted and max is in the right half
    if arr[mid] <= arr[r]:
        return find_Max(arr, mid+1, r)

    # If the left half is sorted and max is in the left half
    return find_Max(arr, l, mid)
