def find_Max(arr, low, high):
    if high < low: 
        return -1
    # Check if array is already sorted 
    elif high == low: 
        return arr[low] 
    # If Middle element is the maximum 
    elif arr[low] < arr[high]: 
        return arr[high]
    # Find middle point 
    mid = low + (high-low)//2 
    # Check if middle element is greater than its next. 
    # This is because the array is a rotated sorted array 
    if mid < high and arr[mid] > arr[mid + 1]: 
        return arr[mid] 
    # Check if the right half is sorted and the maximum lies in 
    # the left half 
    elif mid > low and arr[mid - 1] > arr[mid]: 
        return find_Max(arr, low, mid - 1) 
    # If the array is not rotated
    return find_Max(arr, mid + 1, high)
```

