def find_triplet_array(arr, target, value):
    arr.sort()  # Sort the array in ascending order to facilitate the triplet sum search
    for i in range(len(arr)-2):
        low, high = i+1, len(arr)-1
        while low < high:
            current_sum = arr[i] + arr[low] + arr[high]
            if current_sum == value:
                return arr[i], arr[low], arr[high]
            elif current_sum < value:
                low += 1
            else:
                high -= 1
        if arr[i] + arr[i+1] + arr[i+2] > value:
            break  #Early exit if the sum of the next triplets would exceed the target
    return None  # Return None if no triplet is found
