def dealnnoy_num(n, k):
    if n == 0:
        return 1
    delnnoy = [[0 for _ in range(k+1)] for _ in range(n+1)]
    delnnoy[0][0] = 1
    for i in range(1, n+1):
        for j in range(0, k+1):
            if j == 0:
                delnnoy[i][j] = delnnoy[i-1][j] + delnnoy[i-1][j+1]
            elif j == k:
                delnnoy[i][j] = delnnoy[i-1][j-1]
            else:
                delnnoy[i][j] = delnnoy[i-1][j-1] + delnnoy[i-1][j] + delnnoy[i-1][j+1]
    return delnnoy[n][k]
```

