def dealnnoy_num(n, size):
    if n > size:
        return 0
    dp = [[0] * (size + 1) for _ in range(size + 1)]
    dp[0][0] = dp[1][0] = 1

    for i in range(2, size + 1):
        for j in range(2, size + 1):
