def coin_change(coins, amount, target):
    def dfs(target, coins, memo):
        if target == 0:
            return 1
        if target < 0 or not coins:
            return 0
        if target in memo:
            return memo[target]
        memo[target] = dfs(target - coins[0], coins, memo) + dfs(target, coins[1:], memo)
        return memo[target]

    return dfs(target, sorted(coins), {})
```

