def coin_change(coins, amount, count):
    if amount == 0:
        return count
    if coins == []:
        return 0
    exclude = coin_change(coins[:-1], amount, count)
    include = coin_change(coins[:-1], amount - coins[-1], count + 1) if amount >= coins[-1] else 0
    return exclude + include
