def min_Swaps(src, dest):
    M, N = len(src), len(dest)
    # Find first different digit in each string
    found = False
    src_index = -1
    dest_index = -1
    for i in range(M):
        if src[i] == dest[i]:
            found = True
        if src[i] != dest[i] and not found:
            src_index, dest_index = i, i
    if found:
        min_swaps = 0
        # Count the number of swaps required to match dest
        for i in range(dest_index, N):
            if dest[i] != src[src_index]:
                min_swaps += 1
                src_index = (src_index + 1) % M
        return min_swaps
    return -1
```

