def count_Rotation(arr, n):
    if n <= 1:
        return 0
    start, end = 0, n - 1
    while start < end:
        if arr[start] <= arr[end]:
            return 0
        mid = (start + end) // 2
        if mid < n - 1 and arr[mid] > arr[mid + 1]:
            return mid + 1
        if arr[mid] > arr[start]:
            end = mid - 1
        else:
            start = mid + 1
