def count_Rotation(nums, n):
    low, high = 0, n - 1
    while low < high:
        mid = low + (high - low) // 2
        if mid > 0 and nums[mid] < nums[mid - 1]:
            return mid
        if nums[mid] > nums[high]:
            low = mid + 1
        else:
            high = mid - 1
    return n
