def max_sum_of_three_consecutive(arr, n):
    res = 0
    for i in range(n):
        if i < 2:
            res = max(res, arr[i])
        elif i < 4:
            res = max(res, arr[i] + arr[i-1] + arr[i-2])
        else:
            res = max(res, arr[i] + arr[i-1] + arr[i-2], arr[i] + arr[i-2] + arr[i-3], arr[i] + arr[i-3] + arr[i-4])
    return res
```

```python
def max_sum_of_three_consecutive(lst, k):
    if k < 3:
        return sum(lst)

    max_sum = float('-inf')
    for i in range(k):
        max_sum = max(max_sum, lst[i])
    current_sum = lst[0] + lst[1] + lst[2]
    max_sum = max(max_sum, current_sum)

    for i in range(k, len(lst)):
        current_sum = current_sum - lst[i-k] + lst[i]
        max_sum = max(max_sum, current_sum)

    return max_sum
```

