def min_cost(cost, m, n):
    dp = [[float('inf') for _ in range(n + 1)] for _ in range(m + 1)]
    dp[0][0] = cost[0][0]

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            up = dp[i - 1][j] if i > 0 else float('inf')
            left = dp[i][j - 1] if j > 0 else float('inf')
            dp[i][j] = cost[i][j] + min(up, left)

    return dp[m - 1][n - 1]
