def min_Swaps(s: str, t: str) -> int:
    differing_bits = 0
    swaps = 0
    diff_pos = {"01": 0, "00": 0, "11": 0}

    for bit1, bit2 in zip(s, t):
        if bit1 != bit2:
            differing_bits += 1
            diff_pos[bit1 + bit2] += 1

    if differing_bits % 2 != 0:
        return 0  # It's not possible to make two equal strings with swaps

    for i in range(differing_bits - 1):
        shifts = t[i+1:] + t[:i+1]
        if shifts == s:
            swaps += 1

    return swaps
