def super_seq(str1, str2, m, n, dp=None):
    if dp is None:
        dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct super sequence
    super_seq = []
    i, j = m, n
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            super_seq.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            super_seq.append(str1[i - 1])
            i -= 1
        else:
            super_seq.append(str2[j - 1])
            j -= 1

    # Append remaining characters from the longer string
    while i > 0:
        super_seq.append(str1[i - 1])
        i -= 1
    while j > 0:
        super_seq.append(str2[j - 1])
        j -= 1

    return len(super_seq), ''.join(reversed(super_seq))
