    similar_rows = set()
    for i, row in enumerate(matrix):
        for j in range(i+1, len(matrix)):
            if len(row) == len(matrix[j]) and all(a == b for a, b in zip(row, matrix[j])):
                similar_rows.add(tuple(row))
    return similar_rows
