def find_Points(a, b, x, y):
    # Get the range boundaries
    range_a = (x, a)
    range_b = (y, b)
    
    # Find points that are within either range
    points = []
    for i in range(range_a[0], range_a[1] + 1):
        if i not in range_b:
            points.append(i)
    for i in range(range_b[0], range_b[1] + 1):
        if i not in range_a:
            points.append(i)
            
    # Return the chosen points
    return points
