def find_Min_Diff(arr, size):
    max_left = arr[0]
    min_right = arr[size - 1]
    min_diff = min_right - max_left
    for i in range(1, size):
        if min_right - arr[i] < min_diff:
            min_diff = min_right - arr[i]
        if max_left - arr[i] > min_diff:
            min_diff = max_left - arr[i]
    return min_diff
